(()=>{'use strict';const V=window.HVACVisual;if(!V)return;const box=document.createElement('div');box.className='pipe-visual-box';document.querySelector('.results')?.prepend(box);box.addEventListener('click',e=>{const b=e.target.closest('[data-pipe-check]');if(!b)return;if(b.dataset.pipeCheck==='water'){document.getElementById('w-diameter').value=waterChosen.diameter;document.querySelector('#w-modes [data-mode=check]').click();document.getElementById('w-diameter').focus();}else{const chosen=rows[selected??0]||rows[0];document.getElementById('width').value=chosen.a;document.getElementById('height').value=chosen.b;document.querySelector('#modes [data-mode=check]').click();document.getElementById('width').focus();}});const {section,geometry,button,L,n,svg,label}=V;if(typeof waterRender==='function'){const original=waterRender;waterRender=function(){original();if(!waterChosen)return;const r=waterChosen,x=waterInput(),fill=r.overCapacity?null:r.fill;let drawing=geometry(true,r.diameter,r.diameter,x.q*3600,r.overCapacity?NaN:r.V);if(x.gravity){const level=fill===null?null:151-fill*122;drawing=svg('<defs><clipPath id="drain-cross-section"><circle cx="125" cy="90" r="61"/></clipPath></defs><circle cx="125" cy="90" r="61" fill="#f4faf7" stroke="#60958c" stroke-width="4"/>'+(level!==null?'<rect x="64" y="'+level+'" width="122" height="'+(151-level)+'" fill="#89ced8" clip-path="url(#drain-cross-section)"/>':'')+label(125,17,'Ø '+n(r.diameter)+' mm')+label(125,181,fill===null?L('Vượt năng lực thoát','Above capacity'):L('Độ đầy thực: ','Actual depth: ')+n(fill*100)+'%')+'<path d="M240 90l130 35M240 108l130 35" stroke="#7cab9b" stroke-width="5"/><path d="M257 117l80 22m-7-10 7 10-11 4" fill="none" stroke="#159c8e" stroke-width="3"/>'+label(303,71,L('Độ dốc: ','Slope: ')+n(x.s*100)+'%')+label(303,182,'Q = '+n(x.q*3600)+' m³/h'));}box.innerHTML=section(L('Tiết diện & dòng nước','Pipe section & water flow'),drawing,button('w-flow',L('Lưu lượng','Flow'),n(x.q*3600)+' m³/h')+(waterMode==='check'?button('w-diameter',L('Đường kính trong','Internal diameter'),n(r.diameter)+' mm'):'<button type="button" class="visual-chip" data-pipe-check="water">'+L('Kiểm tra Ø ','Check Ø ')+n(r.diameter)+' mm</button>')+(x.gravity?button('w-slope',L('Độ dốc','Slope'),n(x.s*100)+'%'):button('w-length',L('Chiều dài','Length'),n(x.l)+' m')),x.gravity?L('Hình không theo tỷ lệ. Độ đầy dùng kết quả Manning tại lưu lượng thực, không phải độ đầy tối đa nhập.','Not to scale. Depth is the Manning result at actual flow, not the entered maximum depth.'):L('Mặt cắt dùng đường kính trong của ống. Hình minh họa, không theo tỷ lệ.','Cross-section uses internal pipe diameter. Illustration, not to scale.'));};document.addEventListener('input',()=>{if(!document.getElementById('w-error').hidden)box.innerHTML='';});const clear=waterUpdate;waterUpdate=function(){clear();if(!waterChosen||!document.getElementById('w-error').hidden)box.innerHTML='';};waterUpdate();}else if(typeof render==='function'){const original=render;render=function(r,x){original(r,x);box.innerHTML=section(L('Tiết diện & luồng gió','Duct section & airflow'),geometry(shape==='round',r.a,r.b,x.q*3600,r.V),button('flow',L('Lưu lượng','Flow'),n(x.q*3600)+' m³/h')+(mode==='check'?button('width',shape==='round'?L('Đường kính','Diameter'):L('Chiều rộng','Width'),n(r.a)+' mm')+(shape==='rect'?button('height',L('Chiều cao','Height'),n(r.b)+' mm'):''):'<button type="button" class="visual-chip" data-pipe-check="duct">'+L('Kiểm tra kích thước này','Check this size')+'</button>')+button('vmax',L('Giới hạn vận tốc','Velocity limit'),n(x.v)+' m/s'));};const originalClear=clearResults;clearResults=function(){originalClear();box.innerHTML='';};update();}})();
